const ABBREVIATIONS_DATA = [{"abbr": "Eep", "full": "EEPROM Driver Module (MCAL)", "cat": "ADDR", "catLabel": "Eep Core & Addressing", "sws": "Mod 90 / 0x005A", "meaning": "Trình điều khiển phần cứng EEPROM cấp thấp trong AUTOSAR Classic MCAL."}, {"abbr": "EepBaseAddress", "full": "EEPROM Physical Base Address", "cat": "ADDR", "catLabel": "Eep Core & Addressing", "sws": "ECUC_Eep_00165", "meaning": "Địa chỉ vật lý gốc mà tại đó không gian bộ nhớ Eep bắt đầu."}, {"abbr": "EepSize", "full": "Configured Usable EEPROM Size", "cat": "ADDR", "catLabel": "Eep Core & Addressing", "sws": "ECUC_Eep_00173", "meaning": "Tổng dung lượng logic/vật lý tối đa (256B ở simulator) cho phép truy cập."}, {"abbr": "EepTotalSize", "full": "Physical Silicon Total Capacity", "cat": "ADDR", "catLabel": "Eep Core & Addressing", "sws": "ECUC_Eep_00174", "meaning": "Tổng dung lượng vật lý của chip EEPROM; luôn >= EepSize."}, {"abbr": "EepEraseValue", "full": "EEPROM Erased Cell Value", "cat": "ADDR", "catLabel": "Eep Core & Addressing", "sws": "ECUC_Eep_00193", "meaning": "Giá trị từng byte sau khi Eep_Erase() thành công (0xFF hoặc 0x00)."}, {"abbr": "EepReadUnitSize", "full": "Minimum Hardware Read Unit", "cat": "ADDR", "catLabel": "Eep Core & Addressing", "sws": "ECUC_Eep_00194", "meaning": "Bội số byte tối thiểu cho địa chỉ và độ dài khi gọi Eep_Read()."}, {"abbr": "EepWriteUnitSize", "full": "Minimum Hardware Write Unit", "cat": "ADDR", "catLabel": "Eep Core & Addressing", "sws": "ECUC_Eep_00195", "meaning": "Đơn vị byte tối thiểu khi ghi (thường là 1B với EEPROM thực)."}, {"abbr": "EepEraseUnitSize", "full": "Minimum Hardware Erase Unit", "cat": "ADDR", "catLabel": "Eep Core & Addressing", "sws": "ECUC_Eep_00196", "meaning": "Đơn vị byte tối thiểu bắt buộc khi gọi Eep_Erase() (vd 8B page)."}, {"abbr": "EepDefaultMode", "full": "Default MemIf Operation Mode", "cat": "ADDR", "catLabel": "Eep Core & Addressing", "sws": "ECUC_Eep_00166", "meaning": "Chế độ mặc định nạp sau khi gọi Eep_Init(&Eep_Config)."}, {"abbr": "MEMIF_MODE_SLOW", "full": "Memory Interface Slow Mode", "cat": "ADDR", "catLabel": "Eep Core & Addressing", "sws": "SWS_Eep_00011", "meaning": "Chế độ chạy nền ưu tiên ít tải CPU (Chunk đọc 16B, ghi 8B)."}, {"abbr": "MEMIF_MODE_FAST", "full": "Memory Interface Fast Mode", "cat": "ADDR", "catLabel": "Eep Core & Addressing", "sws": "SWS_Eep_00011", "meaning": "Chế độ truyền tốc độ cao khi Startup/Shutdown (Chunk đọc 64B, ghi 32B)."}, {"abbr": "EepNormalReadBlockSize", "full": "Normal Mode Read Chunk Size", "cat": "ADDR", "catLabel": "Eep Core & Addressing", "sws": "ECUC_Eep_00171", "meaning": "Số byte tối đa đọc mỗi chu kỳ MainFunction khi ở SLOW Mode."}, {"abbr": "EepNormalWriteBlockSize", "full": "Normal Mode Write Chunk Size", "cat": "ADDR", "catLabel": "Eep Core & Addressing", "sws": "ECUC_Eep_00172", "meaning": "Số byte tối đa ghi mỗi chu kỳ MainFunction khi ở SLOW Mode."}, {"abbr": "EepFastReadBlockSize", "full": "Fast Mode Read Chunk Size", "cat": "ADDR", "catLabel": "Eep Core & Addressing", "sws": "ECUC_Eep_00167", "meaning": "Số byte tối đa đọc mỗi chu kỳ MainFunction khi ở FAST Mode."}, {"abbr": "EepFastWriteBlockSize", "full": "Fast Mode Write Chunk Size", "cat": "ADDR", "catLabel": "Eep Core & Addressing", "sws": "ECUC_Eep_00168", "meaning": "Số byte tối đa ghi mỗi chu kỳ MainFunction khi ở FAST Mode."}, {"abbr": "EEPROM", "full": "Electrically Erasable Programmable ROM", "cat": "HW", "catLabel": "Hardware, SPI & Timing", "sws": "Hardware", "meaning": "Bộ nhớ bất khả biến xóa/ghi được từng byte bằng điện áp."}, {"abbr": "SPI", "full": "Serial Peripheral Interface", "cat": "HW", "catLabel": "Hardware, SPI & Timing", "sws": "SWS_Eep_00116", "meaning": "Bus nối tiếp 4 dây kết nối MCU với chip EEPROM ngoài (25LC256)."}, {"abbr": "MOSI", "full": "Master Out Slave In", "cat": "HW", "catLabel": "Hardware, SPI & Timing", "sws": "SPI Bus", "meaning": "Đường truyền lệnh WREN/WRITE và dữ liệu từ MCU xuống chip EEPROM."}, {"abbr": "MISO", "full": "Master In Slave Out", "cat": "HW", "catLabel": "Hardware, SPI & Timing", "sws": "SPI Bus", "meaning": "Đường đọc dữ liệu và thanh ghi trạng thái RDSR từ EEPROM về MCU."}, {"abbr": "CS / SS", "full": "Chip Select / Slave Select", "cat": "HW", "catLabel": "Hardware, SPI & Timing", "sws": "SPI Bus", "meaning": "Chân chọn chip mức thấp; cạnh lên CS kích hoạt chu kỳ lập trình EEPROM."}, {"abbr": "WREN (0x06)", "full": "Write Enable Instruction", "cat": "HW", "catLabel": "Hardware, SPI & Timing", "sws": "SPI EEPROM Cmd", "meaning": "Mã lệnh SPI bắt buộc gửi trước mọi thao tác ghi để bật chốt WEL=1."}, {"abbr": "WRITE (0x02)", "full": "Write Data to Memory Array", "cat": "HW", "catLabel": "Hardware, SPI & Timing", "sws": "SPI EEPROM Cmd", "meaning": "Mã lệnh SPI nạp byte/page dữ liệu vào địa chỉ EEPROM chỉ định."}, {"abbr": "READ (0x03)", "full": "Read Data from Memory Array", "cat": "HW", "catLabel": "Hardware, SPI & Timing", "sws": "SPI EEPROM Cmd", "meaning": "Mã lệnh SPI đọc tuần tự dữ liệu ra từ địa chỉ EEPROM bất kỳ."}, {"abbr": "RDSR (0x05)", "full": "Read Status Register", "cat": "HW", "catLabel": "Hardware, SPI & Timing", "sws": "SPI EEPROM Cmd", "meaning": "Mã lệnh SPI đọc thanh ghi trạng thái chip để thăm dò bit WIP và WEL."}, {"abbr": "WIP", "full": "Write-In-Progress Bit (Bit 0 RDSR)", "cat": "HW", "catLabel": "Hardware, SPI & Timing", "sws": "HW Status Bit", "meaning": "Bit phần cứng = 1 trong ~5ms khi chip EEPROM đang bận lập trình cell."}, {"abbr": "WEL", "full": "Write Enable Latch Bit (Bit 1 RDSR)", "cat": "HW", "catLabel": "Hardware, SPI & Timing", "sws": "HW Status Bit", "meaning": "Bit cho phép ghi nội bộ chip, tự xóa về 0 sau khi ghi xong."}, {"abbr": "ISR (Eep_JobEndIsr)", "full": "Interrupt Service Routine", "cat": "HW", "catLabel": "Hardware, SPI & Timing", "sws": "SWS_Eep_00117", "meaning": "Ngắt hoàn tất phần cứng thúc đẩy Chunk kế nhanh gấp đôi Polling."}, {"abbr": "EepWriteCycleReduction", "full": "Write Cycle Reduction Optimization", "cat": "HW", "catLabel": "Hardware, SPI & Timing", "sws": "SWS_Eep_00024", "meaning": "Đọc so sánh trước khi ghi; bỏ qua Chunk trùng dữ liệu để tăng tuổi thọ."}, {"abbr": "MCAL", "full": "Microcontroller Abstraction Layer", "cat": "STACK", "catLabel": "Memory Stack", "sws": "Layered Arch", "meaning": "Tầng phần mềm thấp nhất tiếp xúc trực tiếp thanh ghi vi điều khiển."}, {"abbr": "Ea", "full": "EEPROM Abstraction (Mod 40)", "cat": "STACK", "catLabel": "Memory Stack", "sws": "SWS_Ea", "meaning": "Lớp trên gọi trực tiếp duy nhất xuống Eep, chia 1 Block thành 3 Sub-Jobs."}, {"abbr": "MemIf", "full": "Memory Abstraction Interface (Mod 22)", "cat": "STACK", "catLabel": "Memory Stack", "sws": "SWS_MemIf", "meaning": "Bộ định tuyến hợp nhất giữa NvM với Ea (EEPROM) hoặc Fee (Flash)."}, {"abbr": "NvM", "full": "NVRAM Manager (Mod 20)", "cat": "STACK", "catLabel": "Memory Stack", "sws": "SWS_NvM", "meaning": "Dịch vụ quản lý Queue, CRC, Retry, ReadAll/WriteAll cho ứng dụng."}, {"abbr": "RTE", "full": "Runtime Environment", "cat": "STACK", "catLabel": "Memory Stack", "sws": "AUTOSAR RTE", "meaning": "Cầu nối trung gian kết nối Client-Server Port từ SWC xuống NvM."}, {"abbr": "SWC", "full": "Software Component", "cat": "STACK", "catLabel": "Memory Stack", "sws": "App Layer", "meaning": "Thành phần ứng dụng (Odometer, UDS Diagnostic), cách ly hoàn toàn với Eep."}, {"abbr": "EcuM", "full": "ECU State Manager", "cat": "STACK", "catLabel": "Memory Stack", "sws": "SWS_EcuM", "meaning": "Khởi tạo Eep_Init(&Eep_Config) trước Ea_Init() ở giai đoạn Startup."}, {"abbr": "BswM", "full": "Basic Software Mode Manager", "cat": "STACK", "catLabel": "Memory Stack", "sws": "SWS_BswM", "meaning": "Điều phối chuyển chế độ MemIf FAST lúc khởi động/tắt máy sang SLOW lúc chạy."}, {"abbr": "SchM", "full": "Schedule Manager", "cat": "STACK", "catLabel": "Memory Stack", "sws": "SWS_SchM", "meaning": "Lập lịch gọi định kỳ Eep_MainFunction() (mặc định 5ms) và vùng găng."}, {"abbr": "Sub-Job (Hdr/Data/Ftr)", "full": "Ea Block Write Sub-Jobs", "cat": "STACK", "catLabel": "Memory Stack", "sws": "Ea Architecture", "meaning": "Ea tách mỗi Block thành Header (0xA5) -> Payload -> Footer (0x5A) qua 3 lệnh Eep_Write."}, {"abbr": "Ea_JobEndNotification", "full": "Job End Success Callback", "cat": "STACK", "catLabel": "Memory Stack", "sws": "SWS_Eep_00141", "meaning": "Hàm callback do Eep gọi lên Ea khi hoàn tất thành công toàn bộ Job."}, {"abbr": "Ea_JobErrorNotification", "full": "Job Error / Cancel Callback", "cat": "STACK", "catLabel": "Memory Stack", "sws": "SWS_Eep_00142", "meaning": "Hàm callback báo lỗi, hủy lệnh Eep_Cancel() hoặc Compare không khớp lên Ea."}, {"abbr": "DET", "full": "Default Error Tracer", "cat": "ERR", "catLabel": "Errors: DET, Runtime & Dem", "sws": "SWS_Det", "meaning": "Module ghi nhận lỗi lập trình/tham số (Mod 90) và Runtime Errors."}, {"abbr": "DEM", "full": "Diagnostic Event Manager", "cat": "ERR", "catLabel": "Errors: DET, Runtime & Dem", "sws": "SWS_Dem", "meaning": "Module quản lý sự kiện chẩn đoán và lưu mã lỗi DTC khi hỏng phần cứng."}, {"abbr": "EEP_E_UNINIT (0x00)", "full": "Driver Not Initialized Error", "cat": "ERR", "catLabel": "Errors: DET, Runtime & Dem", "sws": "SWS_Eep_00047", "meaning": "Báo qua Det_ReportError khi gọi API lúc Driver đang ở MEMIF_UNINIT."}, {"abbr": "EEP_E_INVALID_ADDRESS (0x01)", "full": "Address Out-of-Range / Unaligned", "cat": "ERR", "catLabel": "Errors: DET, Runtime & Dem", "sws": "SWS_Eep_00047", "meaning": "Địa chỉ >= EepSize hoặc không chia hết cho Read/Write/Erase UnitSize."}, {"abbr": "EEP_E_INVALID_DATA (0x02)", "full": "Invalid NULL Data Pointer", "cat": "ERR", "catLabel": "Errors: DET, Runtime & Dem", "sws": "SWS_Eep_00047", "meaning": "Con trỏ DataBufferPtr truyền vào Eep_Read/Write/Compare là NULL_PTR."}, {"abbr": "EEP_E_INVALID_LENGTH (0x03)", "full": "Invalid Data Length Error", "cat": "ERR", "catLabel": "Errors: DET, Runtime & Dem", "sws": "SWS_Eep_00047", "meaning": "Độ dài = 0, Addr + Length > EepSize hoặc lệch đơn vị UnitSize."}, {"abbr": "EEP_E_BUSY (0x04)", "full": "Driver Busy Runtime Error", "cat": "ERR", "catLabel": "Errors: DET, Runtime & Dem", "sws": "SWS_Eep_00047", "meaning": "Runtime Error luôn bật khi gọi lệnh mới lúc Eep đang MEMIF_BUSY."}, {"abbr": "EEP_E_TIMEOUT (0x05)", "full": "Hardware Timeout Runtime Error", "cat": "ERR", "catLabel": "Errors: DET, Runtime & Dem", "sws": "SWS_Eep_00047", "meaning": "Runtime Error kích hoạt khi cờ phần cứng WIP kẹt ở mức 1 quá hạn."}, {"abbr": "EEP_E_INIT_FAILED (0x09)", "full": "Initialization Failure DET", "cat": "ERR", "catLabel": "Errors: DET, Runtime & Dem", "sws": "SWS_Eep_00047", "meaning": "Lỗi DET khi gọi Eep_Init(NULL_PTR) hoặc lỗi phần cứng khi Init."}, {"abbr": "EEP_E_PARAM_POINTER (0x0A)", "full": "Null Parameter Pointer DET", "cat": "ERR", "catLabel": "Errors: DET, Runtime & Dem", "sws": "SWS_Eep_00047", "meaning": "Lỗi DET khi truyền NULL_PTR vào Eep_GetVersionInfo()."}, {"abbr": "MEMIF_BLOCK_INCONSISTENT", "full": "Compare Mismatch Job Result", "cat": "ERR", "catLabel": "Errors: DET, Runtime & Dem", "sws": "SWS_Eep_00056", "meaning": "Kết quả trả về khi Eep_Compare() phát hiện dữ liệu EEPROM lệch với RAM."}, {"abbr": "EEP_E_WRITE_FAILED", "full": "Dem Hardware Write Failure Event", "cat": "ERR", "catLabel": "Errors: DET, Runtime & Dem", "sws": "SWS_Eep_00054", "meaning": "Sự kiện Dem báo về ECU khi Write Verification phát hiện ô nhớ hỏng / Stuck Bit."}];

const hbState = {
  tab1: 0,
  tab2: 0,
  abbrCat: "ALL",
  abbrQuery: ""
};

function switchHbTab1(idx) {
  hbState.tab1 = idx;
  hbState.tab2 = 0;
  for (let i = 0; i <= 6; i++) {
    const b = document.getElementById("hbTab1_" + i);
    if (b) b.classList.toggle("active", i === idx);
  }
  const nav2 = document.getElementById("hbNav2");
  const filterBox = document.getElementById("hbAbbrFilterBox");
  if (idx === 6) {
    if (nav2) nav2.classList.add("hidden");
    if (filterBox) filterBox.classList.remove("hidden");
  } else {
    if (nav2) nav2.classList.remove("hidden");
    if (filterBox) filterBox.classList.add("hidden");
  }
  renderHandbook();
}

function switchHbTab2(idx) {
  hbState.tab2 = idx;
  renderHandbook();
}

function setAbbrCategory(cat) {
  hbState.abbrCat = cat || "ALL";
  ["ALL", "ADDR", "HW", "STACK", "ERR"].forEach((c) => {
    const pill = document.getElementById("catPill_" + c);
    if (pill) pill.classList.toggle("active", c === hbState.abbrCat);
  });
  renderAbbreviationTable();
}

function filterAbbreviationTable() {
  const inp = document.getElementById("abbrSearchInput");
  hbState.abbrQuery = inp ? inp.value.trim() : "";
  renderAbbreviationTable();
}

function highlightMatch(text, query) {
  const safe = escHtml(text);
  if (!query) return safe;
  const qEsc = query.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  try {
    const re = new RegExp("(" + qEsc + ")", "ig");
    return safe.replace(re, "<mark>$1</mark>");
  } catch (e) {
    return safe;
  }
}

function renderAbbreviationTable() {
  const area = document.getElementById("hbContentArea");
  const badge = document.getElementById("abbrCountBadge");
  if (!area) return;

  const q = (hbState.abbrQuery || "").toLowerCase();
  const filtered = ABBREVIATIONS_DATA.filter((item) => {
    if (hbState.abbrCat !== "ALL" && item.cat !== hbState.abbrCat) return false;
    if (!q) return true;
    const hay = `${item.abbr} ${item.full} ${item.catLabel} ${item.sws} ${item.meaning}`.toLowerCase();
    return hay.includes(q);
  });

  if (badge) {
    badge.textContent = `${filtered.length} / ${ABBREVIATIONS_DATA.length} thuật ngữ`;
  }

  if (filtered.length === 0) {
    area.innerHTML = `<div class="hb-card"><h3>Không tìm thấy thuật ngữ phù hợp</h3><p>Không có mục nào khớp với từ khóa <code>${escHtml(hbState.abbrQuery)}</code> trong bộ lọc hiện tại.</p></div>`;
    return;
  }

  const rowsHtml = filtered.map((item) => `
    <tr>
      <td class="mono" style="font-weight:800;color:var(--pri)">${highlightMatch(item.abbr, hbState.abbrQuery)}</td>
      <td>${highlightMatch(item.full, hbState.abbrQuery)}</td>
      <td><span class="state-badge sb-cyan">${escHtml(item.catLabel)}</span></td>
      <td class="mono" style="font-size:11px;color:var(--mut)">${highlightMatch(item.sws, hbState.abbrQuery)}</td>
      <td>${highlightMatch(item.meaning, hbState.abbrQuery)}</td>
    </tr>
  `).join("");

  area.innerHTML = `
    <div class="hb-card">
      <h3>Bảng Tra Cứu 52 Thuật Ngữ &amp; Viết Tắt Chuyên Ngành AUTOSAR Eep</h3>
      <table class="tbl">
        <thead>
          <tr><th>Thuật ngữ / Ký hiệu</th><th>Tên Đầy Đủ</th><th>Phân Nhóm</th><th>SWS / ECUC</th><th>Giải Nghĩa &amp; Vai Trò</th></tr>
        </thead>
        <tbody>${rowsHtml}</tbody>
      </table>
    </div>
  `;
}

function populateEcucDictionaryIntoHandbook() {
  const holder = document.getElementById("hbEcucDynamicList");
  if (!holder) return;
  const rows = Object.keys(defaultConfig).map((k, idx) => {
    const meta = configTooltipData[k] || {};
    return `<tr>
      <td class="mono">${idx + 1}</td>
      <td class="mono" style="font-weight:700;color:var(--pri)">${escHtml(k)}</td>
      <td class="mono" style="font-size:11px">${escHtml(meta.sws || "")}</td>
      <td class="mono" style="font-size:11px">${escHtml(JSON.stringify(defaultConfig[k]))}</td>
      <td>${escHtml(meta.desc || "")}</td>
    </tr>`;
  }).join("");
  holder.innerHTML = `
    <table class="tbl">
      <thead><tr><th>#</th><th>ECUC Parameter</th><th>SWS / ECUC Ref</th><th>Mặc Định</th><th>Giải Thích Chi Tiết</th></tr></thead>
      <tbody>${rows}</tbody>
    </table>
  `;
}

function renderHandbook() {
  if (hbState.tab1 === 6) {
    renderAbbreviationTable();
    return;
  }
  const topic = HANDBOOK_TABS[hbState.tab1] || HANDBOOK_TABS[0];
  const nav2 = document.getElementById("hbNav2");
  if (nav2) {
    nav2.innerHTML = topic.subtabs.map((st, i) =>
      `<button class="hb-tab2${i === hbState.tab2 ? " active" : ""}" onclick="switchHbTab2(${i})">${escHtml(st.title)}</button>`
    ).join("");
  }
  const area = document.getElementById("hbContentArea");
  const sub = topic.subtabs[hbState.tab2] || topic.subtabs[0];
  if (area && sub) {
    area.innerHTML = sub.html;
    if (hbState.tab1 === 5 && hbState.tab2 === 3) {
      populateEcucDictionaryIntoHandbook();
    }
  }
}

document.addEventListener("DOMContentLoaded", () => {
  try {
    const savedRaw = document.body.getAttribute("data-saved-cfg");
    if (savedRaw) {
      const parsed = JSON.parse(savedRaw);
      Object.keys(defaultConfig).forEach((k) => {
        if (parsed && parsed[k] !== undefined) defaultConfig[k] = parsed[k];
      });
    }
  } catch (e) {}
  setupConfigTooltips();
  switchCfgTab(0);
  switchInspTab(0);
  loadScenario("S1");
  renderHandbook();
});
